def tensor_product(dim1, dim2):
    """
    Compute the tensor product of two dimensional vectors.

    Args:
        dim1 (int or list): Dimension of the first vector.
        dim2 (int or list): Dimension of the second vector.

    Returns:
        np.ndarray: Tensor product of the two vectors.
    """
    if isinstance(dim1, list) and isinstance(dim2, list):
        result = np.zeros((len(dim1), len(dim2)))
        for i in range(len(dim1)):
            for j in range(len(dim2)):
                result[i, j] = dim1[i] * dim2[j]
        return result
    elif isinstance(dim1, int) and isinstance(dim2, int):
        result = np.zeros((dim1, dim2))
        for i in range(dim1):
            for j in range(dim2):
                result[i, j] = dim1 * dim2
        return result
    else:
        raise TypeError("dim1 and dim2 must be either int or list")
