def tensor_product(dim1, dim2):
    '''Input:
    dim1: int or list, dimension of the first tensor
    dim2: int or list, dimension of the second tensor
    Output:
    out: A list representing the tensor product of the two input dimensions.
    '''
    if isinstance(dim1, list) and isinstance(dim2, list):
        result = []
        for i in range(len(dim1)):
            for j in range(len(dim2)):
                result.append([dim1[i], dim2[j]])
        return result
    elif isinstance(dim1, list):
        result = []
        for i in range(len(dim1)):
            result.append([dim1[i]])
        return result
    elif isinstance(dim2, list):
        result = []
        for i in range(len(dim2)):
            result.append([dim2[i]])
        return result
    else:
        return [[dim1]] * [dim2]
